import {profileMetrics,recentSolvesMarkup} from './profile-extras.js?v=profile-compact-1';
import {escapeHtml as h} from './community-model.js';
import {rankCup} from './rewards.js?v=upgrade-2';
import {findCompany} from './companies.js?v=social-1';
import {monthCalendar} from './profile-calendar.js?v=profile-2';
import {languageNames,profileDetails} from './profile-fields.js?v=profile-2';
export const publicProfileHref=p=>'./community.html#user/'+encodeURIComponent(p.username||p.public_id||'');
export function profileAvatar(p,large=false){return p?.avatar_url&&/^https:\/\//.test(p.avatar_url)?'<img class="avatar '+(large?'large':'')+'" src="'+h(p.avatar_url)+'" alt="" referrerpolicy="no-referrer" loading="lazy">':'<span class="avatar '+(large?'large':'')+'">'+h((p?.display_name||p?.username||'?').trim().charAt(0).toUpperCase())+'</span>';}
export function profileIcon(p){return '<a class="user-profile-icon" href="'+publicProfileHref(p)+'" aria-label="View '+h(p.display_name||p.username||'learner')+' profile" title="View ByteQuest profile"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="8" r="3"/><path d="M5 21v-2a7 7 0 0 1 14 0v2M18 3h4v4M22 3l-5 5"/></svg></a>';}
function organization(p){let d;try{d=profileDetails(p);}catch{return '';}if(!d.organization_name)return '';const c=findCompany(d.organization_name),icon=c?'<img src="'+c.file+'" alt="" loading="lazy">':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m3 8 9-5 9 5M4 9h16M5 10v9m5-9v9m4-9v9m5-9v9M3 21h18"/></svg>',label='<span class="organization-icon">'+icon+'</span><span>'+h(d.organization_name)+'</span>';return d.organization_url?'<a class="profile-organization" href="'+h(d.organization_url)+'" target="_blank" rel="noopener noreferrer" title="'+h(d.organization_type)+' · provided by this user">'+label+'</a>':'<span class="profile-organization" title="'+h(d.organization_type)+' · provided by this user">'+label+'</span>';}
function linkedin(p){let d;try{d=profileDetails(p);}catch{return '';}return d.linkedin_url?'<a class="profile-linkedin" href="'+h(d.linkedin_url)+'" target="_blank" rel="noopener noreferrer" aria-label="Open LinkedIn profile" title="LinkedIn"><img src="./assets/companies/linkedin.svg" alt=""></a>':'';}
export function profileMarkup(r,{catalogCount=0,catalog=[],admin=false,canFollow=true}={}){
 const p=r.profile,rank=Number(r.ranking?.rank)||0,medal=({1:'gold',2:'silver',3:'bronze'})[rank]||'',calendar=monthCalendar(r.stats.days,r.stats.serverDay),skills=r.insights?.skills||[],languages=(r.insights?.languages||[]).filter(x=>languageNames[x.language]).sort((a,b)=>(Number(b.solved)||0)-(Number(a.solved)||0)),points=Number(r.ranking?.points||0),streak=Number(r.stats.streak)||0;
 return '<section class="white-card profile-main-card"><div class="profile-hero">'+profileAvatar(p,true)+'<div class="profile-identity"><span class="eyebrow">PROFILE</span><h2 class="profile-title '+(medal?'medal-'+medal:'')+'"><span class="rank-name-text">'+h(p.display_name)+'</span>'+rankCup(rank)+'<span class="profile-inline-rank">'+(rank?'#'+rank+' global':'Unranked')+'</span>'+(p.is_admin?'<span class="admin-badge">Admin</span>':'')+'</h2><div class="profile-username-line"><span>@'+h(p.username)+(p.discoverable?'':' · private profile')+'</span><span id="profilePresenceStatus" class="presence" role="status"></span>'+linkedin(p)+'</div><div class="profile-connections"><button data-connections="followers"><strong>'+Number(r.followers||0)+'</strong> followers</button><span>·</span><button data-connections="following"><strong>'+Number(r.following||0)+'</strong> following</button></div>'+organization(p)+'</div><div class="profile-actions">'+(r.isOwn?'<a class="button secondary" href="#edit">Edit profile</a>':!canFollow?'<a class="button secondary" href="#edit">Create a discoverable profile to follow</a>':'<button id="followBtn" class="button primary">'+(r.isFollowing?'Following ✓':'Follow +')+'</button>'+(r.isFollowing?'<button id="messageFriend" class="button secondary">Message</button>':''))+'</div></div>'+(p.bio?'<p class="profile-bio">'+h(p.bio)+'</p>':'')+profileMetrics(r.stats,points,catalogCount)+recentSolvesMarkup(r.insights?.recentSolves||[],catalog)+'<div class="profile-expertise"><section><h3>Skills practiced</h3><div class="profile-skill-list">'+(skills.length?skills.map(s=>'<span class="skill-chip">'+h(s.name)+'<small>'+Number(s.solved)+' solved</small></span>').join(''):'<p class="muted">Skills appear as problems are solved.</p>')+'</div></section><section><h3>Languages used</h3><div class="profile-language-list">'+(languages.length?languages.map(l=>'<span class="language-chip" data-language="'+h(l.language)+'">'+languageNames[l.language]+'<small>'+Number(l.solved)+' solved</small></span>').join(''):'<p class="muted">Languages appear after accepted submissions.</p>')+'</div></section></div><div class="calendar-heading"><h3>Solving calendar</h3><span>Last 12 calendar months</span></div><div class="activity-scroll month-calendar-scroll" tabindex="0" aria-label="Scroll solving calendar"><div class="month-calendar" role="img" aria-label="Accepted solve days grouped by month">'+calendar.months.map(m=>'<section class="calendar-month" aria-label="'+h(m.title)+'"><span class="calendar-month-label" title="'+h(m.title)+'">'+h(m.label)+'</span><div class="calendar-month-grid">'+m.cells.map(c=>c?'<span class="calendar-day '+(c.active?'solved':'')+'" title="'+c.date+(c.active?': accepted solve':': no solve')+'"></span>':'<span class="calendar-padding" aria-hidden="true"></span>').join('')+'</div></section>').join('')+'</div></div><div class="activity-legend"><span>'+calendar.start+' → '+calendar.end+'</span><span>■ Accepted solve day</span></div><p class="calendar-note">Streaks count consecutive UTC days with accepted solves.</p>'+(r.isOwn&&admin?'<a class="button secondary manage-creators" href="#roles">Manage creators ↗</a>':'')+'</section>';
}
